		build = loadSealed(buildDir);
		checkBuild(build, cfg);
		const m = build.manifest;
		if (m.filesRoot !== before.filesRoot || m.allowlistHash !== before.allowlistHash || m.originsHash !== before.originsHash) throw new SignetError("build", `${buildDir} is not the build that was proposed as #${id}`);
